mapper.sql:
FROM t_record r LEFT JOIN t_category c ON c.id = r.category_id
r.deleted_at IS NULL AND r.status = 'PENDING' AND r.type = #{condition.type} AND r.category_id = #{condition.categoryId}
AND (r.title LIKE #{condition.keywordPattern} ESCAPE '/' OR r.description LIKE #{condition.keywordPattern} ESCAPE '/')

mapper.select:
SELECT r.id, r.type, r.status, r.completed_at, r.title, r.category_id, c.name AS category_name,
       r.location, r.occurred_at, r.publisher_id, r.created_at


LIMIT #{limit} OFFSET #{offset}

mapper.sql:
FROM t_record r
LEFT JOIN t_category c ON c.id = r.category_id

    r.deleted_at IS NULL
    AND r.publisher_id = #{condition.publisherId}
    AND r.type = #{condition.type}
    AND r.status = #{condition.status}

mapper.select:
SELECT r.id, r.title, r.description, r.category_id, r.location
FROM t_record r

    r.deleted_at IS NULL
    AND 
    AND r.type = #{type}
    AND r.category_id = #{categoryId}

ORDER BY r.created_at DESC, r.id DESC
LIMIT #{limit}
